namespace docking.widgets.table;



using docking;
using docking;

public class GTableTextCellEditor : DefaultCellEditor {
	private static readonly object TABLE_FOCUS_CELL_HIGHLIGHT_BORDER =
		"Table.focusCellHighlightBorder";

	private UndoRedoKeeper undoRedoKeeper;

	public GTableTextCellEditor(JTextField textField) : base(textField)
    {
		setClickCountToStart(2);

		textField.setBorder(UIManager.getBorder(TABLE_FOCUS_CELL_HIGHLIGHT_BORDER));

		undoRedoKeeper = DockingUtils.installUndoRedo(textField);
	}

	/* @Override */
	public bool stopCellEditing() {
		if (base.stopCellEditing()) {
			undoRedoKeeper.clear();
			return true;
		}
		return false;
	}

	/* @Override */
	public void cancelCellEditing() {
		base.cancelCellEditing();
		undoRedoKeeper.clear();
	}
}
